        JsonNode media = listMedia(evidenceKey);
        assertThat(media).hasSize(2);
        assertThat(media.get(1).get("status").asText()).isEqualTo("ACTIVE");
        assertThat(media.get(1).get("version").asInt()).isEqualTo(2);
    }
